-- Struktur Tabel `cache_locks`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `cache_locks`;
CREATE TABLE `cache_locks` (
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `owner` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expiration` bigint NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_locks_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Struktur Tabel `facilities`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `facilities`;
CREATE TABLE `facilities` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nama` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipe` enum('ruang_kelas','aula','laboratorium','alat','lapangan') COLLATE utf8mb4_unicode_ci NOT NULL,
  `lokasi` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kapasitas` int unsigned DEFAULT NULL,
  `deskripsi` text COLLATE utf8mb4_unicode_ci,
  `status` enum('aktif','dalam_perbaikan','nonaktif') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'aktif',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `facilities_status_index` (`status`),
  KEY `facilities_tipe_index` (`tipe`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data untuk tabel `facilities` (9 baris)
INSERT INTO `facilities` (`id`, `nama`, `tipe`, `lokasi`, `kapasitas`, `deskripsi`, `status`, `created_at`, `updated_at`) VALUES
(1, 'A303', 'ruang_kelas', 'Gedung E', 50, 'terdapat proyektor, ac, tv, mic siap pakai', 'aktif', '2026-09-24 02:32:17', '2026-09-24 02:32:17'),
(2, 'Ruang A101', 'ruang_kelas', 'Gedung A, Lantai 1', 50, 'Ruang kelas ber-AC dengan proyektor, whiteboard, dan sound system standar.', 'aktif', '2026-09-24 02:45:19', '2026-09-24 02:45:19'),
(3, 'Ruang B203', 'ruang_kelas', 'Gedung B, Lantai 2', 35, 'Ruang kelas kecil, saat ini sedang dalam perbaikan unit pendingin udara.', 'dalam_perbaikan', '2026-09-24 02:45:19', '2026-09-24 02:45:19'),
(4, 'Lab Komputer A', 'laboratorium', 'Gedung C, Lantai 3', 40, 'Lab komputer dengan 40 PC i7, koneksi LAN gigabit, dan proyektor presentasi.', 'aktif', '2026-09-24 02:45:19', '2026-09-24 02:45:19'),
(5, 'Lab Komputer C', 'laboratorium', 'Gedung E, Lantai 2', 30, 'Lab multimedia dan komputasi grafis dengan dual monitor.', 'aktif', '2026-09-24 02:45:19', '2026-09-24 02:45:19'),
(6, 'Aula Utama Kampus', 'aula', 'Gedung Rektorat, Lantai 1', 300, 'Aula serbaguna berkapasitas besar untuk seminar, wisuda, dan kuliah umum.', 'aktif', '2026-09-24 02:45:19', '2026-09-24 02:45:19'),
(7, 'Aula FSM', 'aula', 'Gedung AP, Lantai 4', 150, 'Aula fakultas untuk kegiatan rapat akbar, sidang himpunan, dan pameran.', 'aktif', '2026-09-24 02:45:19', '2026-09-24 02:45:19'),
(8, 'Lapangan Basket', 'lapangan', 'Area Olahraga Barat', 100, 'Lapangan basket outdoor dengan penerangan lampu malam.', 'aktif', '2026-09-24 02:45:19', '2026-09-24 02:45:19'),
(9, 'Sound System Portable & Wireless Mic', 'alat', 'Ruang Perlengkapan BAA', NULL, '1 unit active speaker portable 12 inch dan 2 wireless microphone.', 'aktif', '2026-09-24 02:45:19', '2026-09-24 02:45:19');

-- -------------------------------------------------------------
-- Struktur Tabel `failed_jobs`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `failed_jobs`;
CREATE TABLE `failed_jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `connection` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `queue` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `exception` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `failed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `failed_jobs_uuid_unique` (`uuid`),
  KEY `failed_jobs_connection_queue_failed_at_index` (`connection`,`queue`,`failed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Struktur Tabel `job_batches`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `job_batches`;
CREATE TABLE `job_batches` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_jobs` int NOT NULL,
  `pending_jobs` int NOT NULL,
  `failed_jobs` int NOT NULL,
  `failed_job_ids` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `options` mediumtext COLLATE utf8mb4_unicode_ci,
  `cancelled_at` int DEFAULT NULL,
  `created_at` int NOT NULL,
  `finished_at` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Struktur Tabel `jobs`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `jobs`;
CREATE TABLE `jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `queue` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempts` smallint unsigned NOT NULL,
  `reserved_at` int unsigned DEFAULT NULL,
  `available_at` int unsigned NOT NULL,
  `created_at` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `jobs_queue_index` (`queue`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Struktur Tabel `migrations`
