-- -------------------------------------------------------------
-- Struktur Tabel `reports`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `reports`;
CREATE TABLE `reports` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `facility_id` bigint unsigned NOT NULL,
  `kategori` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `deskripsi` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `foto_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('baru','diproses','selesai','ditolak') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'baru',
  `catatan_resolusi` text COLLATE utf8mb4_unicode_ci,
  `resolved_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `reports_resolved_by_foreign` (`resolved_by`),
  KEY `reports_facility_status_index` (`facility_id`,`status`),
  KEY `reports_user_id_index` (`user_id`),
  CONSTRAINT `reports_facility_id_foreign` FOREIGN KEY (`facility_id`) REFERENCES `facilities` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `reports_resolved_by_foreign` FOREIGN KEY (`resolved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `reports_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data untuk tabel `reports` (8 baris)
INSERT INTO `reports` (`id`, `user_id`, `facility_id`, `kategori`, `deskripsi`, `foto_path`, `status`, `catatan_resolusi`, `resolved_by`, `created_at`, `updated_at`) VALUES
(1, 3, 2, 'kerusakan', 'Proyektor plafon sering mati mendadak setelah 15 menit pemakaian dan lampu indikator error berkedip merah saat kuliah berlangsung.', 'reports/sample-proyektor.png', 'baru', NULL, NULL, '2026-09-27 04:55:07', '2026-09-27 04:55:07'),
(2, 3, 4, 'kerusakan', 'Unit pendingin ruangan AC di baris belakang meneteskan air ke meja komputer PC-12 dan PC-13 sehingga membahayakan peralatan listrik.', 'reports/sample-ac.png', 'diproses', 'Teknisi pendingin ruangan sedang membongkar saluran pipa drainase dan melakukan pembersihan filter evaporator.', 2, '2026-09-25 04:55:07', '2026-09-28 04:55:07'),
(3, 3, 6, 'kerusakan', 'Kabel konektor HDMI panggung utama putus dan jack mikrofon wireless channel 2 berderik kencang saat digerakkan.', 'reports/sample-sound.png', 'selesai', 'Kabel konektor HDMI telah diganti dengan kabel baru berisolasi tinggi dan jack receiver mic wireless telah disolder ulang serta lolos uji suara.', 2, '2026-09-22 04:55:07', '2026-09-26 04:55:07'),
(4, 3, 3, 'lainnya', 'Permintaan penambahan sofa santai dan dispenser air minum galon di sudut belakang ruang kelas B203 untuk relaksasi mahasiswa.', NULL, 'ditolak', 'Laporan ditolak. Ruang B203 diperuntukkan murni sebagai ruang perkuliahan teori standar, usulan fasilitas tambahan disarankan melalui proposal perlengkapan BAA.', 2, '2026-09-19 04:55:07', '2026-09-20 04:55:07'),
(5, 3, 8, 'kebersihan', 'Sisa botol minuman plastik dan sampah bungkus makanan berserakan di tribun penonton barat setelah pertandingan sparing kemarin sore.', NULL, 'selesai', 'Petugas kebersihan telah mengangkut sampah di seluruh area tribun barat dan menempatkan dua tong sampah tambahan di samping lapangan.', 2, '2026-09-24 04:55:07', '2026-09-25 04:55:07'),
(6, 3, 5, 'kerusakan', 'Tiga unit mouse optik pada meja PC-05, PC-06, dan PC-08 scroll wheel-nya macet dan klik kiri tidak responsif saat praktikum.', NULL, 'diproses', 'Penggantian 3 unit mouse sedang menunggu alokasi periferal pengganti dari gudang perlengkapan IT.', 2, '2026-09-28 04:55:07', '2026-09-28 23:55:07'),
(7, 3, 7, 'kerusakan', 'Lampu sorot LED di sisi kanan panggung utama mati total sehingga area pembicara tampak gelap saat gladi resik seminar.', 'reports/sample-lampu.png', 'baru', NULL, NULL, '2026-09-28 20:55:07', '2026-09-28 20:55:07'),
(8, 3, 9, 'kerusakan', 'Baterai rechargeable microphone wireless habis sangat cepat (< 15 menit) dan charger portable unit terasa sangat panas saat diisi daya.', NULL, 'baru', NULL, NULL, '2026-09-29 02:55:07', '2026-09-29 02:55:07');

-- -------------------------------------------------------------
-- Struktur Tabel `reservations`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `reservations`;
CREATE TABLE `reservations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `facility_id` bigint unsigned NOT NULL,
  `tanggal` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `tujuan_penggunaan` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('pending','approved','rejected','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `processed_by` bigint unsigned DEFAULT NULL,
  `cancelled_reason` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `reservations_processed_by_foreign` (`processed_by`),
  KEY `reservations_conflict_check_index` (`facility_id`,`tanggal`,`start_time`,`end_time`),
  KEY `reservations_user_status_index` (`user_id`,`status`),
  CONSTRAINT `reservations_facility_id_foreign` FOREIGN KEY (`facility_id`) REFERENCES `facilities` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `reservations_processed_by_foreign` FOREIGN KEY (`processed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `reservations_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data untuk tabel `reservations` (2 baris)
INSERT INTO `reservations` (`id`, `user_id`, `facility_id`, `tanggal`, `start_time`, `end_time`, `tujuan_penggunaan`, `status`, `processed_by`, `cancelled_reason`, `created_at`, `updated_at`) VALUES
(1, 3, 2, '2026-09-24', '08:00:00', '10:00:00', 'Perkuliahan Algoritma dan Pemrograman', 'approved', 2, NULL, '2026-09-24 02:45:19', '2026-09-24 02:45:19'),
(2, 3, 4, '2026-09-24', '13:00:00', '15:00:00', 'Praktikum Basis Data', 'approved', 2, NULL, '2026-09-24 02:45:19', '2026-09-24 02:45:19');

-- -------------------------------------------------------------
-- Struktur Tabel `sessions`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
